const TYPE_LABEL={club:'Club',miembro:'Miembro',competidor:'Competidor',marca:'Marca',federacion:'Federación',profesional:'Profesional / Representante',media:'Media / Creador',espectador:'Espectador'};
const REVIEW_STATES=[['under_review','En revisión'],['needs_information','Solicitar información'],['verified','Verificar'],['limited','Limitar'],['suspended','Suspender'],['rejected','Rechazar']];
const READINESS_LABEL={smtp:'SMTP transaccional',legal_controller:'Responsable legal y privacidad',owner_mfa:'Protección crítica Owner',backup_export:'Exportación externa de backup',restore_drill:'Simulacro de restauración',monitoring:'Monitorización y alertas',incident_runbook:'Respuesta ante incidentes'};
function adminOnly(){return state.session?.platform_admin===true;}
function permissionLabel(key){return ({'social.act_as_club':'Social como Club','profile.public.manage':'Perfil público','showcase.manage':'Showcase','relations.manage':'Mi red','contacts.manage':'Contactos'})[key]||key;}
function clean(value){return String(value??'').trim();}
function metricNumber(value){return new Intl.NumberFormat(kxLocaleTag(kxGetLocale()),{maximumFractionDigits:0}).format(Number(value||0));}
function metricMoney(value){return new Intl.NumberFormat(kxLocaleTag(kxGetLocale()),{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(Number(value||0));}
function metricBytes(value){const n=Number(value||0);if(!Number.isFinite(n)||n<=0)return '0 MB';const units=['B','KB','MB','GB','TB'];let v=n,i=0;while(v>=1024&&i<units.length-1){v/=1024;i++;}return `${v.toLocaleString(kxLocaleTag(kxGetLocale()),{maximumFractionDigits:i<2?0:2})} ${units[i]}`;}

function metricPercent(value){const n=Number(value);return Number.isFinite(n)?`${n.toLocaleString(kxLocaleTag(kxGetLocale()),{minimumFractionDigits:1,maximumFractionDigits:1})} %`:'—';}
function marketplaceAnalyticsPanel(market){
  if(!market?.ok)return `<section class="kx-platform-section" id="owner-showcase"><div class="section-title"><div><span class="page-kicker">SHOWCASE MARKETPLACE</span><h3>Marketplace Analytics</h3></div></div><p class="muted">La capa de marketplace está disponible, pero todavía no hay datos agregados que mostrar.</p></section>`;
  const s=market.stats||{},series=Array.isArray(market.series)?market.series:[];
  return `<section class="kx-platform-section kx-market-owner" id="owner-showcase"><div class="section-title"><div><span class="page-kicker">SHOWCASE MARKETPLACE</span><h3>Marketplace Analytics · ${Number(market.days||30)} días</h3></div></div><div class="alert"><strong>Separación financiera</strong><span>GMV es volumen vendido por vendedores. No es ingreso de KOMBAX. Comisión KOMBAX por transacción configurada: ${metricMoney(Number(s.platform_transaction_fee_minor||0)/100)}.</span></div><div class="kx-platform-stats"><article><span>Proveedores</span><strong>${metricNumber(s.providers_total)}</strong></article><article><span>Solicitudes vendedor</span><strong>${metricNumber(s.seller_applications)}</strong></article><article><span>Vendedores verificados</span><strong>${metricNumber(s.seller_verified)}</strong><small>${metricPercent(s.seller_approval_rate)}</small></article><article><span>Listos para vender</span><strong>${metricNumber(s.seller_ready)}</strong><small>${metricPercent(s.seller_ready_rate)}</small></article><article><span>Stripe operativo</span><strong>${metricNumber(s.stripe_ready)}</strong></article><article><span>Productos publicados</span><strong>${metricNumber(s.products_published)}</strong></article><article><span>Productos comprables</span><strong>${metricNumber(s.products_commerce)}</strong><small>${metricPercent(s.commerce_product_rate)}</small></article><article><span>Pedidos</span><strong>${metricNumber(s.orders)}</strong></article><article><span>GMV vendedores</span><strong>${metricMoney(Number(s.gmv_minor||0)/100)}</strong></article><article><span>Compradores</span><strong>${metricNumber(s.buyers)}</strong></article><article><span>Reembolsos</span><strong>${metricNumber(s.refunds)}</strong><small>${metricPercent(s.refund_rate)}</small></article><article><span>Incidencias</span><strong>${metricNumber(s.incidents)}</strong><small>${metricPercent(s.incident_rate)}</small></article></div>${series.length?`<div class="kx-market-series"><table><thead><tr><th>Fecha</th><th>Pedidos</th><th>GMV</th><th>Incidencias</th></tr></thead><tbody>${series.slice(-14).map(x=>`<tr><td>${esc(x.date||x.metric_date||'')}</td><td>${metricNumber(x.orders)}</td><td>${metricMoney(Number(x.gmv_minor||0)/100)}</td><td>${metricNumber(x.incidents)}</td></tr>`).join('')}</tbody></table></div>`:''}</section>`;
}
function marketplaceVerificationPanel(market){
  const sellers=Array.isArray(market?.seller_queue)?market.seller_queue:[],buyers=Array.isArray(market?.buyer_queue)?market.buyer_queue:[],policies=Array.isArray(market?.policies)?market.policies:[];
  return `<section class="kx-platform-section" id="owner-market-verifications"><div class="section-title"><div><span class="page-kicker">VERIFICACIONES · MARKETPLACE</span><h3>Vendedores y compradores</h3></div></div><div class="kx-owner-verify-columns"><div><h4>Vendedores</h4>${sellers.length?`<div class="kx-platform-review-list">${sellers.map(x=>`<article><div><strong>${esc(x.provider_name||x.legal_name||'Vendedor')}</strong><small>${esc(x.provider_type||'')} · ${esc(x.status||'')} · ${dtFmt(x.updated_at)}</small><p>${x.identity_verified?'✓ Identidad KOMBAX':'○ Identidad pendiente'} · ${x.policies_ready?'✓ Políticas':'○ Políticas pendientes'} · ${x.selling_ready?'✓ Venta activa':'○ Venta pendiente'}</p></div><button class="btn btn-primary btn-sm" data-market-seller-review="${esc(x.id)}">Revisar</button></article>`).join('')}</div>`:empty('Sin solicitudes de vendedor','Las nuevas solicitudes aparecerán aquí.')}</div><div><h4>Compradores</h4>${buyers.length?`<div class="kx-platform-review-list">${buyers.map(x=>`<article><div><strong>${esc(x.name||'Comprador')}</strong><small>${esc(x.country||'')} · ${esc(x.status||'')} · ${metricNumber(x.documents_count)} documento(s)</small></div><button class="btn btn-ghost btn-sm" data-market-buyer-review="${esc(x.id)}">Revisar</button></article>`).join('')}</div>`:empty('Sin verificaciones de comprador','La identidad reforzada es opcional para compras normales.')}</div></div><div class="kx-market-policy-list owner"><h4>Documentos contractuales</h4>${policies.map(p=>`<article class="kx-market-policy"><header><div><strong>${esc(p.title)}</strong><small>${esc(p.code)} · ${esc(p.version)}</small></div><span class="kx-market-status ${p.legal_review_status==='approved'?'ok':'pending'}">${p.legal_review_status==='approved'?'Revisión jurídica aprobada':'Revisión jurídica pendiente'}</span></header></article>`).join('')||'<p class="muted">Sin documentos vigentes.</p>'}</div></section>`;
}
