function openCommercialEntitlementReview(item,onDone){
  const days=Number(item.requested_days||item.detail?.requested_days||0)||0;
  openForm({title:`Activación · ${item.entitlement_code}`,subtitle:`${days?`${days} días · `:''}${item.subject_name||item.subject_type||'Organización'}`,fields:[{name:'decision',label:'Decisión',type:'select',required:true,value:'activate',options:[{value:'activate',label:'Activar después de validar contratación/pago'},{value:'reject',label:'Rechazar solicitud'}]},{name:'note',label:'Nota de Administración',type:'textarea',required:true,minLength:5,maxLength:1000,rows:4,full:true,help:'Esta acción no realiza ningún cobro. Solo habilita la activación tras validar el proceso comercial correspondiente.'}],submitText:'Guardar decisión',onSubmit:async v=>{await repos.platformAdmin.decideCommercialEntitlement(item.id,v.decision,v.note);toast(v.decision==='activate'?'Activación habilitada':'Solicitud rechazada');await onDone?.();}});
}

