async function openMarketplaceBuyerReview(item,onDone){
  try{
    const detail=await repos.platformAdmin.marketplaceBuyerDetail(item.id),r=detail?.request||item,docs=Array.isArray(detail?.documents)?detail.documents:[],events=Array.isArray(detail?.events)?detail.events:[];
    const body=`<div class="kx-market-buyer-review"><div class="kx-market-facts"><span>Nombre <strong>${esc(r.full_name||'—')}</strong></span><span>País <strong>${esc(r.country||'—')}</strong></span><span>Estado <strong>${esc(r.status||'—')}</strong></span><span>Documentos <strong>${docs.length}</strong></span></div>${r.reason?`<div class="alert"><strong>Motivo/contexto</strong><span>${esc(r.reason)}</span></div>`:''}<section><h4>Documentos privados</h4>${docs.length?docs.map(d=>`<article class="kx-market-doc"><span>${esc(d.document_type)} · ${esc(d.mime_type)} · ${metricBytes(d.bytes)}</span><button class="btn btn-ghost btn-sm" data-market-doc="${esc(d.storage_path)}">Abrir documento</button></article>`).join(''):'<p class="muted">No hay documentos adjuntos.</p>'}</section><section><h4>Trazabilidad</h4>${events.map(e=>`<p class="muted">${dtFmt(e.created_at)} · ${esc(e.event_type)} · ${esc(e.from_status||'—')} → ${esc(e.to_status||'—')}</p>`).join('')||'<p class="muted">Sin eventos adicionales.</p>'}</section><button class="btn btn-primary" id="market-buyer-decision">Resolver verificación</button></div>`;
    const modal=openDetail({title:'Verificación de comprador',subtitle:'Identidad reforzada opcional · documentos privados',body,width:'850px'});
    modal.wrap.querySelectorAll('[data-market-doc]').forEach(b=>b.addEventListener('click',async()=>{try{const url=await repos.platformAdmin.verificationDocumentUrl(b.dataset.marketDoc);window.open(url,'_blank','noopener,noreferrer');}catch(error){setError(error);}}));
    modal.wrap.querySelector('#market-buyer-decision')?.addEventListener('click',()=>openForm({title:'Resolver identidad del comprador',subtitle:'Verificar exige al menos un documento privado activo.',fields:[{name:'status',label:'Decisión',type:'select',required:true,value:r.status==='submitted'?'under_review':r.status,options:[{value:'under_review',label:'En revisión'},{value:'needs_information',label:'Solicitar información'},{value:'verified',label:'Verificar identidad'},{value:'rejected',label:'Rechazar'}]},{name:'note',label:'Nota de revisión',type:'textarea',full:true,maxLength:2000,required:true,value:r.review_note||''}],submitText:'Guardar decisión',onSubmit:async v=>{await repos.platformAdmin.marketplaceBuyerReview(r.id,v.status,v.note);toast('Verificación de comprador actualizada');modal.close();await onDone?.();}}));
  }catch(error){setError(error);}
}
function metricsPanel(metrics){
  if(!metrics?.ok)return `<section class="kx-platform-section"><div class="section-title"><div><span class="page-kicker">MÉTRICAS Y CONSUMO</span><h3>KOMBAX Analytics</h3></div></div><p class="muted">La capa de métricas está preparada; faltan datos agregados para mostrar la serie.</p></section>`;
  const latest=metrics.latest||{},totals=metrics.period_totals||{},top=Array.isArray(metrics.top_clubs)?metrics.top_clubs:[],ret=metrics.retention||{};
  return `<section class="kx-platform-section"><div class="section-title"><div><span class="page-kicker">MÉTRICAS Y CONSUMO</span><h3>KOMBAX Analytics · ${metricNumber(metrics.days||90)} días</h3></div></div>
    <p class="muted">Métricas agregadas no identificativas para producto, capacidad, costes y venta. El histórico de detalle puede purgarse sin perder estas medidas.</p>
    <div class="kx-platform-stats"><article><span>Clubes activos</span><strong>${metricNumber(latest.active_clubs)}</strong></article><article><span>Cuentas</span><strong>${metricNumber(latest.accounts_total)}</strong></article><article><span>Alumnos activos</span><strong>${metricNumber(latest.active_students)}</strong></article><article><span>Storage actual</span><strong>${metricBytes(latest.storage_bytes)}</strong></article><article><span>Sesiones periodo</span><strong>${metricNumber(totals.sessions)}</strong></article><article><span>Asistencias</span><strong>${metricNumber(totals.attendance)}</strong></article><article><span>Pagos validados</span><strong>${metricNumber(totals.payments)}</strong><small>${metricMoney(totals.payment_amount)}</small></article><article><span>Showcase leads</span><strong>${metricNumber(totals.showcase_leads)}</strong></article><article><span>Social mensajes</span><strong>${metricNumber(totals.social_messages)}</strong></article><article><span>Push enviados</span><strong>${metricNumber(totals.push_sent)}</strong></article></div>
    ${top.length?`<div class="kx-platform-review-list">${top.slice(0,10).map(c=>`<article><div><strong>${esc(c.nombre||'Club')}</strong><small>${metricNumber(c.active_students)} alumnos · ${metricNumber(c.sessions)} sesiones · ${metricNumber(c.attendance)} asistencias · ${metricNumber(c.messages)} mensajes · ${metricNumber(c.showcase_leads)} leads</small></div><div><strong>${metricBytes(c.storage_bytes)}</strong><small>storage</small></div></article>`).join('')}</div>`:''}
    <div class="alert"><strong>Retención automatizada</strong><span>Notificaciones: ${metricNumber(ret.notifications_keep_days||180)} días · Invitaciones vencidas: ${metricNumber(ret.invitation_history_days||30)} días · Conversaciones borradas por ambos: ${metricNumber(ret.deleted_conversations_days||30)} días · Detalle deportivo: ${metricNumber(ret.sports_detail_keep_days||730)} días. Finanzas, verificación y auditoría siguen políticas de trazabilidad específicas.</span></div>
  </section>`;
}
function clubVerificationStatus(app,docs=[]){
  const pub=app?.datos_publicos||{},ver=app?.datos_verificacion||{};
  const checks=[
    ['Identidad del club',clean(app?.nombre_publico).length>=2&&clean(ver.nombre_legal).length>=2,'Nombre comercial y nombre legal'],
    ['Responsable autorizado',clean(ver.responsable).length>=2&&clean(ver.rol_responsable).length>=2,'Responsable y cargo'],
    ['Contacto oficial',clean(ver.email_oficial).includes('@')&&clean(ver.telefono).length>=6,'Email y teléfono'],
    ['Ubicación',clean(pub.ubicacion).length>=2,'Población / zona'],
    ['Actividad deportiva',Array.isArray(pub.disciplinas)&&pub.disciplinas.length>0,'Al menos una disciplina'],
    ['Evidencia contrastable',clean(ver.evidencia).length>=3,'Web, red, federación, registro u otra referencia'],
    ['Acreditación privada',docs.some(d=>d.estado==='active'),'Al menos un documento activo']
  ];
  return {checks,complete:checks.every(x=>x[1])};
}
function detailValue(label,value){return `<div class="kx-admin-club-stats"><span>${esc(label)} <strong>${esc(clean(value)||'—')}</strong></span></div>`;}

