  openForm({title:'Resolver denuncia',subtitle:`${item.objetivo_tipo} · ${item.motivo}`,fields:[{name:'estado',label:'Resultado',type:'select',required:true,value:'resuelta',options:[{value:'resuelta',label:'Resuelta'},{value:'descartada',label:'Descartada'}]},{name:'accion',label:'Acción',type:'select',required:true,value:'ninguna',options:actions.map(([value,label])=>({value,label}))},{name:'resolucion',label:'Motivo / resolución',type:'textarea',full:true,rows:5,maxLength:1500}],submitText:'Aplicar',onSubmit:async v=>{const action=v.estado==='descartada'?'ninguna':v.accion;await repos.kombaxSocial.moderate(item.id,v.estado,v.resolucion||'',action);toast('Denuncia actualizada');await onDone();}});
