      {name:'email_oficial',label:'Email oficial · privado',type:'email',required:true},{name:'telefono',label:'Teléfono oficial · privado',required:true},{name:'direccion',label:'Dirección administrativa o zona de actividad · privada',full:true},
      {name:'responsable',label:'Responsable autorizado',required:true},{name:'rol_responsable',label:'Cargo',required:true},{name:'plan_codigo',label:'Plan solicitado',type:'select',required:true,value:'premium',options:[{value:'club',label:'KOMBAX Club · 29 € Founder'},{value:'premium',label:'KOMBAX Premium · 47 € Founder'},{value:'enterprise',label:'KOMBAX Enterprise · 79 € Founder'}],full:true},{name:'billing_cycle',label:'Facturación',type:'select',required:true,value:'monthly',options:[{value:'monthly',label:'Mensual'},{value:'annual',label:'Anual estándar · -16 %'}],full:true}
