      const datos_verificacion={forma_entidad:v.forma_entidad||'',nombre_legal:v.nombre_legal||'',cif:v.cif||'',email_oficial:v.email_oficial||'',telefono:v.telefono||'',direccion:v.direccion||'',responsable:v.responsable||'',rol_responsable:v.rol_responsable||'',evidencia:'Alta directa validada por Administrador KOMBAX'};
