async function requestCriticalOwnerOtp(){
  const challenge=await backend.beginPlatformCriticalAccess();
  return new Promise((resolve,reject)=>{
    openForm({title:'Confirmación crítica Owner',subtitle:`Esta operación es excepcionalmente destructiva. Se ha enviado un código de 6 dígitos a ${challenge.email_masked||challenge.email}.`,fields:[{name:'otp',label:'Código de seguridad',required:true,pattern:'[0-9]{6}',help:'Solo se exige para acciones críticas; el acceso normal al panel usa únicamente tu contraseña.'}],submitText:'Autorizar operación crítica',onSubmit:async v=>{try{await backend.completePlatformCriticalAccess(challenge.email,v.otp,challenge.challenge_id);toast('Autorización crítica verificada');resolve(true);}catch(error){reject(error);throw error;}}});
  });
}

export async function renderPlatformAdmin(){
  if(!adminOnly()){setMainHtml(empty('Acceso restringido','Esta sección requiere autorización global KOMBAX.'));return;}
  setMainHtml(`<div class="kx-platform-admin">${pageHeader('Administración KOMBAX','Consola global de clubes, identidades, verificaciones, moderación y estado de la plataforma.','','KOMBAX')}<div id="kx-platform-admin-body"><div class="loading-card">Cargando consola…</div></div></div>`);
  const box=document.getElementById('kx-platform-admin-body');
  try{
    const [dash,contract,readiness,incidents,recentProfiles,privacyQueue,metrics,marketplace,commercial,commercialRequests]=await Promise.all([repos.platformAdmin.dashboard(),repos.platformAdmin.releaseContract().catch(()=>null),repos.platformAdmin.pilotReadiness(),repos.platformAdmin.clientIncidents(50),repos.platformAdmin.profiles('',40),repos.platformAdmin.deletionQueue(null,50).catch(()=>[]),repos.platformAdmin.metrics(90).catch(()=>null),repos.platformAdmin.marketplace(30).catch(()=>null),repos.platformAdmin.commercialServices(100).catch(()=>null),repos.platformAdmin.commercialRequests(100).catch(()=>({ok:false,plan_requests:[],activation_requests:[]}))]);
    const counts=dash?.counts||{},clubs=Array.isArray(dash?.clubs)?dash.clubs:[],audit=Array.isArray(dash?.recent_audit)?dash.recent_audit:[],pending=Array.isArray(dash?.pending_verifications)?dash.pending_verifications:[],reports=Array.isArray(dash?.open_reports)?dash.open_reports:[];
    box.innerHTML=`<section class="kx-admin-mode">${icon('key',{size:24})}<div><small>LLAVE GLOBAL ACTIVA</small><strong>Administrador de plataforma KOMBAX</strong><span>Este acceso está separado de tu rol dentro de cualquier club y todas las acciones sensibles quedan trazadas.</span></div></section>
      <nav class="kx-owner-control-nav"><button type="button" data-owner-jump="owner-summary">Resumen</button><button type="button" data-owner-jump="owner-analytics">Analytics</button><button type="button" data-owner-jump="owner-verifications">Verificaciones</button><button type="button" data-owner-jump="owner-showcase">Showcase</button><button type="button" data-owner-jump="owner-commercial">Servicios</button><button type="button" data-owner-jump="owner-operations">Operaciones</button></nav>
      <div id="owner-summary" class="kx-platform-stats"><article><span>Clubes</span><strong>${Number(counts.clubs||0)}</strong></article><article><span>Cuentas</span><strong>${Number(counts.accounts||0)}</strong></article><article><span>Membresías</span><strong>${Number(counts.memberships||0)}</strong></article><article><span>Perfiles públicos</span><strong>${Number(counts.profiles||0)}</strong></article><article><span>Verificaciones pendientes</span><strong>${Number(counts.pending_verifications||0)}</strong></article><article><span>Denuncias abiertas</span><strong>${Number(counts.open_reports||0)}</strong></article><article><span>Showcase activo</span><strong>${Number(counts.showcase_items||0)}</strong></article><article><span>Conexiones de red</span><strong>${Number(counts.relations||0)}</strong></article><article><span>Solicitudes de red</span><strong>${Number(counts.pending_relations||0)}</strong></article><article><span>Contactos pendientes</span><strong>${Number(counts.pending_contacts||0)}</strong></article></div>
      <div id="owner-analytics">${metricsPanel(metrics)}</div>
      ${marketplaceAnalyticsPanel(marketplace)}
      <section class="kx-platform-section"><div class="section-title"><div><span class="page-kicker">CLUBES</span><h3>Clubes KOMBAX</h3></div><button class="btn btn-primary btn-sm" id="kx-platform-create-club">+ Crear club</button></div>${clubs.length?`<div class="kx-platform-clubs">${clubs.map(c=>`<button type="button" data-platform-club="${esc(c.id)}"><div>${icon('dojo',{size:22})}<span><strong>${esc(c.nombre)}</strong><small>${Number(c.miembros||0)} miembros activos · ${c.activo?'Activo':'Inactivo'} · Social ${c.social_profile_id?'OK':'pendiente'}</small></span></div>${icon('chevronRight',{size:18})}</button>`).join('')}</div>`:empty('Sin clubes','No hay clubes registrados.')}</section>
      <section class="kx-platform-section"><div class="section-title"><div><span class="page-kicker">USUARIOS Y PERFILES</span><h3>Identidades KOMBAX</h3></div></div><div class="kx-platform-search"><input id="kx-platform-profile-query" type="search" placeholder="Buscar perfil o club"><button class="btn btn-ghost" id="kx-platform-profile-search">Buscar</button></div><div id="kx-platform-profile-results">${profileRows(recentProfiles)}</div></section>
      <section class="kx-platform-section"><div class="section-title"><div><span class="page-kicker">ADMINISTRACIÓN GLOBAL</span><h3>Acceso temporal por entidad o cuenta</h3></div></div><p class="muted">Busca Club, Federación, Marca, Competidor, Profesional o cuenta. Cada entrada exige motivo, caduca automáticamente y queda ligada a esta sesión Owner.</p><div class="kx-platform-search"><input id="kx-platform-entity-query" type="search" placeholder="Buscar entidad, email o cuenta"><button class="btn btn-primary" id="kx-platform-entity-search">Buscar entidad</button></div><div id="kx-platform-entity-results"></div></section>
      <section class="kx-platform-section" id="owner-verifications"><div class="section-title"><div><span class="page-kicker">VERIFICACIONES</span><h3>Clubes, perfiles y entidades</h3></div></div>${pending.length?`<div class="kx-platform-review-list">${pending.map(x=>`<article><div><strong>${esc(x.nombre_publico||'Solicitud')}</strong><small>${esc(TYPE_LABEL[x.tipo]||x.tipo)} · ${esc(x.estado)} · ${dtFmt(x.actualizado_en||x.creado_en)}</small></div><button class="btn btn-primary btn-sm" data-admin-review="${esc(x.id)}">Revisar</button></article>`).join('')}</div>`:empty('Sin verificaciones pendientes','La cola de verificación está al día.')}</section>
      ${marketplaceVerificationPanel(marketplace)}
      ${commercialServicesPanel(commercial)}
      ${commercialPlanRequestsPanel(commercialRequests)}
      <div id="owner-operations"></div>
      <section class="kx-platform-section"><div class="section-title"><div><span class="page-kicker">MODERACIÓN E INCIDENCIAS</span><h3>Denuncias abiertas</h3></div></div>${reports.length?`<div class="kx-platform-review-list">${reports.map(x=>`<article><div><strong>${esc(x.motivo)}</strong><small>${esc(x.objetivo_tipo)} · ${esc(x.estado)} · ${dtFmt(x.creado_en)}</small>${x.detalle?`<p>${esc(x.detalle)}</p>`:''}</div><button class="btn btn-ghost btn-sm" data-admin-report="${esc(x.id)}">Gestionar</button></article>`).join('')}</div>`:empty('Sin denuncias abiertas','La cola de moderación está al día.')}</section>
      <section class="kx-platform-section"><div class="section-title"><div><span class="page-kicker">PRIVACIDAD</span><h3>Solicitudes de eliminación de cuenta</h3></div></div><p class="muted">Esta cola pertenece exclusivamente a Administración/Privacidad. Moderación de contenidos no puede revisar ni completar eliminaciones.</p>${privacyQueue.length?`<div class="kx-platform-review-list">${privacyQueue.map(x=>`<article><div><strong>Cuenta ${esc(String(x.perfil_id||'').slice(0,8))}</strong><small>${esc(x.alcance)} · ${esc(x.estado)} · ${dtFmt(x.solicitado_en)}</small>${x.motivo?`<p>${esc(x.motivo)}</p>`:''}</div><div class="row-actions">${x.estado==='confirmed'?`<button class="btn btn-danger btn-sm" data-admin-delete-execute="${esc(x.id)}">Ejecutar eliminación</button>`:x.estado==='completed'?'<span>Completada</span>':x.estado==='rejected'?'<span>Rechazada</span>':`<button class="btn btn-ghost btn-sm" data-admin-delete-review="${esc(x.id)}">Revisar privacidad</button>`}</div></article>`).join('')}</div>`:empty('Sin solicitudes de privacidad','No hay eliminaciones de cuenta pendientes.')}</section>
      ${readinessPanel(readiness,incidents)}
      <section class="kx-platform-section"><div class="section-title"><div><span class="page-kicker">AUDITORÍA</span><h3>Actividad reciente de representación</h3></div></div>${audit.length?`<div class="kx-platform-audit">${audit.map(a=>`<article><div><strong>${esc(a.accion)}</strong><small>${dtFmt(a.creado_en)} · ${esc(a.objeto_tipo||'acción')}</small></div><code>${esc(a.actor_nombre||a.actor_perfil_id||'')}</code></article>`).join('')}</div>`:empty('Sin actividad reciente','Las acciones auditadas aparecerán aquí.')}</section>
      ${contract?`<section class="kx-platform-section kx-technical-panel"><div class="section-title"><div><span class="page-kicker">ESTADO TÉCNICO</span><h3>Build ${Number(contract.build||window.UW_CONFIG?.release?.build||20077)}</h3></div></div><div class="kx-admin-club-stats"><span>Identidades <strong>${contract.identity_context?'OK':'Pendiente'}</strong></span><span>Perfiles públicos <strong>${contract.public_profiles?'OK':'Pendiente'}</strong></span><span>Social media <strong>${contract.social_media?'OK':'Pendiente'}</strong></span><span>Showcase <strong>${contract.showcase_actions?'OK':'Pendiente'}</strong></span><span>Admin global <strong>${contract.platform_admin?'OK':'Pendiente'}</strong></span></div><p class="muted">Las herramientas avanzadas se encuentran en la pestaña Mantenimiento de la Consola KOMBAX.</p></section>`:''}`;

    const reload=()=>renderPlatformAdmin();
    box.querySelectorAll('[data-owner-jump]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.ownerJump)?.scrollIntoView({behavior:'smooth',block:'start'})));
    box.querySelectorAll('[data-market-seller-review]').forEach(b=>{const item=(marketplace?.seller_queue||[]).find(x=>String(x.id)===String(b.dataset.marketSellerReview));if(item)b.addEventListener('click',()=>openMarketplaceSellerReview(item,reload));});
    box.querySelectorAll('[data-market-buyer-review]').forEach(b=>{const item=(marketplace?.buyer_queue||[]).find(x=>String(x.id)===String(b.dataset.marketBuyerReview));if(item)b.addEventListener('click',()=>openMarketplaceBuyerReview(item,reload));});
    box.querySelectorAll('[data-commercial-review]').forEach(b=>{const item=(commercial?.ticketing_queue||[]).find(x=>String(x.id)===String(b.dataset.commercialReview));if(item)b.addEventListener('click',()=>openCommercialServiceReview(item,reload));});
    box.querySelectorAll('[data-commercial-plan-review]').forEach(b=>{const item=(commercialRequests?.plan_requests||[]).find(x=>String(x.id)===String(b.dataset.commercialPlanReview));if(item)b.addEventListener('click',()=>openCommercialPlanRequestReview(item,reload));});
    box.querySelectorAll('[data-commercial-entitlement-review]').forEach(b=>{const item=(commercialRequests?.activation_requests||[]).find(x=>String(x.id)===String(b.dataset.commercialEntitlementReview));if(item)b.addEventListener('click',()=>openCommercialEntitlementReview(item,reload));});
    document.getElementById('kx-platform-create-club')?.addEventListener('click',()=>openCreateClub(reload));
    box.querySelectorAll('[data-platform-club]').forEach(b=>b.addEventListener('click',()=>openClubAdmin(b.dataset.platformClub)));
    box.querySelectorAll('[data-admin-review]').forEach(b=>{const item=pending.find(x=>String(x.id)===String(b.dataset.adminReview));if(item)b.addEventListener('click',()=>openVerification(item,reload));});
    box.querySelectorAll('[data-admin-report]').forEach(b=>{const item=reports.find(x=>String(x.id)===String(b.dataset.adminReport));if(item)b.addEventListener('click',()=>openReport(item,reload));});
    box.querySelectorAll('[data-admin-delete-review]').forEach(b=>{const item=privacyQueue.find(x=>String(x.id)===String(b.dataset.adminDeleteReview));if(!item)return;b.addEventListener('click',()=>openForm({title:'Revisión de privacidad',subtitle:'Solo Owner/Administración de privacidad puede cambiar el estado. Confirmar habilita el ejecutor, pero no elimina todavía ningún dato.',fields:[{name:'estado',label:'Estado',type:'select',required:true,value:item.estado==='requested'?'in_review':item.estado,options:[{value:'in_review',label:'En revisión'},{value:'needs_information',label:'Solicitar información'},{value:'confirmed',label:'Confirmar eliminación'},{value:'rejected',label:'Rechazar'}]},{name:'nota_retencion',label:'Datos que deben conservarse y fundamento',type:'textarea',required:true,minLength:10,maxLength:1200,rows:4,full:true,value:item.nota_retencion||''},{name:'resolucion',label:'Resolución / observaciones',type:'textarea',maxLength:2000,rows:4,full:true,value:item.resolucion||''}],submitText:'Guardar revisión',onSubmit:async v=>{await repos.platformAdmin.reviewDeletion(item.id,v.estado,v.resolucion,v.nota_retencion);toast('Solicitud de privacidad actualizada');await reload();}}));});
    box.querySelectorAll('[data-admin-delete-execute]').forEach(b=>{const item=privacyQueue.find(x=>String(x.id)===String(b.dataset.adminDeleteExecute));if(!item)return;b.addEventListener('click',()=>openForm({title:'Ejecutar eliminación de cuenta',subtitle:'Operación irreversible. Elimina contenido y archivos eliminables, bloquea/anonimiza Auth y conserva únicamente trazas técnicas o legalmente exigibles.',fields:[{name:'confirmacion',label:'Escribe ELIMINAR para continuar',required:true,pattern:'ELIMINAR',help:'La operación no puede deshacerse.'}],submitText:'Ejecutar eliminación irreversible',onSubmit:async v=>{if(String(v.confirmacion||'').trim()!=='ELIMINAR')throw new Error('Escribe ELIMINAR exactamente para confirmar.');await requestCriticalOwnerOtp();const result=await repos.platformAdmin.executeDeletion(item.id);if(result?.ok!==true)throw new Error('La eliminación no quedó confirmada.');toast('Cuenta eliminada y anonimizada');await reload();}}));});
    const bindProfiles=(root=box)=>{
      root.querySelectorAll('[data-admin-profile-open]').forEach(b=>b.addEventListener('click',()=>openKombaxPublicProfile(b.dataset.adminProfileOpen)));
      root.querySelectorAll('[data-admin-moderator]').forEach(b=>b.addEventListener('click',()=>openForm({title:'Rol de moderación global',subtitle:'Permite moderar contenido, pero no concede acceso a documentos privados de verificación.',fields:[{name:'rol',label:'Rol',type:'select',value:'moderador',options:[{value:'moderador',label:'Moderador'},{value:'administrador',label:'Administrador de moderación'}]},{name:'activo',label:'Activo',type:'checkbox',value:true,full:true}],submitText:'Guardar',onSubmit:async v=>{await repos.platformAdmin.setModerator(b.dataset.adminModerator,v.rol,v.activo===true);toast('Rol global actualizado');}})));
      root.querySelectorAll('[data-admin-verifier]').forEach(b=>b.addEventListener('click',()=>openForm({title:'Acceso a verificación privada',subtitle:'Permiso separado para consultar documentos acreditativos. Toda asignación exige un motivo auditable.',fields:[{name:'activo',label:'Acceso activo',type:'checkbox',value:true,full:true},{name:'motivo',label:'Motivo',type:'textarea',required:true,minLength:10,maxLength:500,full:true}],submitText:'Guardar permiso',onSubmit:async v=>{await repos.platformAdmin.setVerifier(b.dataset.adminVerifier,v.activo===true,v.motivo);toast('Permiso de verificación actualizado');}})));
    };
    bindProfiles();
    const search=async()=>{const target=document.getElementById('kx-platform-profile-results'),q=document.getElementById('kx-platform-profile-query')?.value||'';target.innerHTML='<div class="loading-card">Buscando perfiles…</div>';try{const rows=await repos.platformAdmin.profiles(q,100);target.innerHTML=profileRows(rows);bindProfiles(target);}catch(error){target.innerHTML=empty('No se pudo buscar',humanError(error));}};
    document.getElementById('kx-platform-profile-search')?.addEventListener('click',search);
    document.getElementById('kx-platform-profile-query')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();search();}});
    const searchEntities=async()=>{const target=document.getElementById('kx-platform-entity-results'),q=document.getElementById('kx-platform-entity-query')?.value||'';target.innerHTML='<div class="loading-card">Buscando entidades…</div>';try{const rows=await repos.platformAdmin.entities(q,100);target.innerHTML=entityRows(rows);target.querySelectorAll('[data-admin-entity]').forEach(b=>{const entity=rows.find(x=>String(x.id)===String(b.dataset.adminEntity)&&String(x.entidad_tipo)===String(b.dataset.adminEntityType));if(entity)b.addEventListener('click',()=>openEntityAdmin(entity));});}catch(error){target.innerHTML=empty('No se pudo buscar',humanError(error));}};
    document.getElementById('kx-platform-entity-search')?.addEventListener('click',searchEntities);
    document.getElementById('kx-platform-entity-query')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();searchEntities();}});
    box.querySelectorAll('[data-readiness-control]').forEach(b=>b.addEventListener('click',()=>{const control=b.dataset.readinessControl,row=readiness?.manual?.[control]||{};openForm({title:READINESS_LABEL[control]||control,subtitle:'Atestación manual y auditada. Confirma el control solo si la evidencia existe y ha sido comprobada.',fields:[{name:'verified',label:'Control verificado',type:'checkbox',value:row.verified===true,full:true},{name:'evidence',label:'Evidencia / referencia',type:'textarea',required:true,minLength:10,maxLength:1000,full:true,value:row.evidence||''}],submitText:'Guardar atestación',onSubmit:async v=>{await repos.platformAdmin.setPilotReadiness(control,v.verified===true,v.evidence);toast('Control de piloto actualizado');await renderPlatformAdmin();}});}));
  }catch(error){box.innerHTML=empty('No se pudo cargar Administración KOMBAX',humanError(error));}
}
